// Guard module boundaries in a test so the monolith stays carve-able
@AnalyzeClasses(packages = "com.shop")
class ModuleBoundaryTest {
  @ArchTest
  static final ArchRule sales_cannot_reach_billing_internals =
    noClasses().that().resideInAPackage("..sales..")
      .should().accessClassesThat()
      .resideInAPackage("..billing.internal..");

  @ArchTest
  static final ArchRule cross_module_only_via_public_api =
    classes().that().resideInAPackage("..sales..")
      .should().onlyDependOnClassesThat()
      .resideInAnyPackage("..sales..", "..billing.api..", "java..");
}

// Same customer_id, two models — each context owns its own shape
namespace Sales {
  export interface Customer { id: string; pipelineStage: "lead" | "won"; leadSource: string }
}
namespace Billing {
  export interface Customer { id: string; taxId: string; paymentMethod: string; creditTermsDays: number }
}

// Anti-corruption layer: translate at the edge, never share the model
function salesToBilling(s: Sales.Customer, taxId: string): Billing.Customer {
  return { id: s.id, taxId, paymentMethod: "unset", creditTermsDays: 30 };
}

// Event notification: thin — consumers must call back for details
bus.publish({ type: "OrderPlaced", orderId: "o_123" });

// Event-carried state transfer: carries data — no callback needed
bus.publish({
  type: "OrderPlaced",
  orderId: "o_123",
  correlationId: "req_88f",       // thread the whole flow for tracing
  items: [{ sku: "A1", qty: 2 }],
  totalCents: 4200,               // consumers keep their own copy
});

// Write path: validate against the normalized write model
async function handleSetPrice(cmd: SetPrice) {
  await writeDb.update("skus", cmd.sku, { priceCents: cmd.priceCents });
  await bus.publish({ type: "PriceChanged", sku: cmd.sku, priceCents: cmd.priceCents });
}

// Projection: build a read model shaped for the query, not the write
bus.on("PriceChanged", e =>
  searchIndex.upsert(e.sku, { priceCents: e.priceCents }));

// Queries hit the read model only — never the write store
const hits = await searchIndex.search({ q: "boots", maxPriceCents: 9000 });

CRITERIA = {"max_words": 100, "min_useful_score": 0.9}

def evaluate(dataset):
    passed = 0
    for row in dataset:
        out = summarize(row["source"])
        auto_ok = len(out.split()) <= CRITERIA["max_words"]
        faithful = judge(out, row["source"])  # 0..1
        if auto_ok and faithful >= CRITERIA["min_useful_score"]:
            passed += 1
    return passed / len(dataset)

ALLOWED = {"billing", "technical", "other"}

def route(model_output: str):
    label = model_output.strip().lower()
    if label not in ALLOWED:
        raise ValueError(f"unexpected label: {label!r}")
    # never: db.execute(model_output) or eval(model_output)
    return db.execute(
        "SELECT * FROM tickets WHERE type = %s",
        (label,),
    )

// Emit ONE wide event at the end of each unit of work.
logger.info("request.complete", {
  request_id, user_id, build_id, region,        // identity + deploy context
  route, status, duration_ms,
  feature_flags: flags.active(),                // arbitrary high-cardinality
